import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_reduction_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Kernel to compute min reduction across dimension=1 for a 3D tensor (B, D1, D2).
// Output shape is (B, D2).
__global__ void min_reduction_dim1_kernel(const float* input, float* output, int B, int D1, int D2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * D2;
    if (idx < total) {
        int b = idx / D2;
        int c = idx % D2;
        float val = input[b * D1 * D2 + 0 * D2 + c];
        for (int row = 1; row < D1; row++) {
            float candidate = input[b * D1 * D2 + row * D2 + c];
            val = (candidate < val ? candidate : val);
        }
        output[b * D2 + c] = val;
    }
}

torch::Tensor min_reduction_cuda(torch::Tensor input, int dim) {
    // For simplicity, this custom kernel handles dimension=1 for a 3D tensor: (B, D1, D2).
    TORCH_CHECK(input.dim() == 3, "Input must be a 3D tensor.");
    TORCH_CHECK(dim == 1, "This custom kernel only supports reduction over dimension=1.");

    int B = input.size(0);
    int D1 = input.size(1);
    int D2 = input.size(2);

    auto output = torch::zeros({B, D2}, input.options());

    const int block_size = 256;
    const int num_blocks = (B * D2 + block_size - 1) / block_size;

    min_reduction_dim1_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        B, D1, D2
    );

    return output;
}
"""

